{
  "edits": [
    {
      "old": "  - Buttons are level-sensitive; no edge memory.",
      "new": "  - Automatic buttons are edge-triggered; manual direction buttons remain level."
    },
    {
      "old": "    tmp_Completed : BOOL := FALSE;
END_VAR",
      "new": "    tmp_Completed : BOOL := FALSE;
    tmp_TrigA : R_TRIG;
    tmp_TrigB : R_TRIG;
    tmp_TrigC : R_TRIG;
END_VAR"
    },
    {
      "old": "// Update automatic-mode latches with stop priority.",
      "new": "tmp_TrigA(CLK := ButtonA);
tmp_TrigB(CLK := ButtonB);
tmp_TrigC(CLK := ButtonC);

// Update automatic-mode latches with stop priority."
    },
    {
      "old": "// Movement to B starts only in automatic mode and when SensorA and ButtonA are true.
// It is cleared as soon as SensorB detects the product.
tmp_MoveToB := (tmp_MoveToB OR (Mode AND SensorA AND ButtonA)) AND NOT SensorB;

// Movement to C starts similarly from B and is cleared by SensorC.
tmp_MoveToC := (tmp_MoveToC OR (Mode AND SensorB AND ButtonB)) AND NOT SensorC;

// Completion light is set only in automatic mode when product is at C and ButtonC is pressed.
// It remains on while SensorC is true and is cleared when SensorC goes false.
tmp_Completed := (tmp_Completed OR (Mode AND SensorC AND ButtonC)) AND SensorC;",
      "new": "// Automatic commands require a rising edge on the matching button while the product sensor is true.
// Movement to B starts on a ButtonA edge with SensorA true and clears when SensorB detects the product.
tmp_MoveToB := (tmp_MoveToB OR (Mode AND SensorA AND tmp_TrigA.Q)) AND NOT SensorB;

// Movement to C starts on a ButtonB edge with SensorB true and clears when SensorC detects the product.
tmp_MoveToC := (tmp_MoveToC OR (Mode AND SensorB AND tmp_TrigB.Q)) AND NOT SensorC;

// Completion light is set on a ButtonC edge with SensorC true and remains on while SensorC is true.
// It clears as soon as the product is removed from SensorC.
tmp_Completed := (tmp_Completed OR (Mode AND SensorC AND tmp_TrigC.Q)) AND SensorC;"
    }
  ]
}
